from fractions import Fraction
import math

def is_rational_square(f):
    """Checks if a Fraction f is the square of a rational number."""
    if f < 0:
        return False
    if f == 0:
        return True

    # Convert to simplified fraction P/Q
    P = f.numerator
    Q = f.denominator

    # Check if P and Q are perfect squares
    sqrt_P = int(math.isqrt(P))
    if sqrt_P * sqrt_P != P:
        return False

    sqrt_Q = int(math.isqrt(Q))
    if sqrt_Q * sqrt_Q != Q:
        return False

    return True

def check_solution(a_val):
    """Calculates b^2 for a given rational a and checks if it's a rational square."""
    if a_val == 2:
        return "Undefined (a=2)"

    # b^2 = a^2 - 1 - 2/(a - 2)
    try:
        a = Fraction(a_val)
        b_squared = a*a - 1 - Fraction(2, a - 2)

        if b_squared < 0:
            return f"Negative: {b_squared}"

        if is_rational_square(b_squared):
            return f"Solution Found! b^2 = {b_squared}"
        else:
            return f"Not a square: {b_squared}"
    except Exception as e:
        return f"Error: {e}"

# Candidate values for a close to 0 (excluding 0)
a_near_0 = [
    Fraction(1, 5), Fraction(2, 5), Fraction(1, 4), Fraction(3, 4),
    Fraction(1, 10), Fraction(5, 10) # 1/2 is already tested in notes
]

# Candidate values for a close to 1 (excluding 1)
a_near_1 = [
    Fraction(6, 5), Fraction(5, 4), Fraction(7, 5), Fraction(3, 5)
]

print("--- Testing values near a=0 ---")
for a in a_near_0:
    print(f"a = {a}: {check_solution(a)}")

print("\n--- Testing values near a=1 ---")
for a in a_near_1:
    print(f"a = {a}: {check_solution(a)}")
